mapper.select:
select token_id, member_number, token, scope, label, created_at, last_used_at, revoked_at
from tbl_widget_token
where token = #{token}

mapper.update:
update tbl_widget_token
set revoked_at = now()
where token_id = #{tokenId}

update tbl_widget_token
set last_used_at = CLOCK_TIMESTAMP()
where token_id = #{tokenId}
